export const jsonLdScript = (text: string): string => `<script type="application/ld+json">${text}</script>`

// 一页 HTML 走真实抽取器，按 collect-evidence 的 persist-schema / deep-persist-schema 形状组成 schema 证据行。
export function schemaEvidenceFromHtml(
  html: string,
  opts: { id: string; source: string; sitePageId?: string | null },
): DiagnosisEvidenceRow {
  const schema = extractSchema(html)
  return {
    id: opts.id,
    type: 'schema',
    claimLevel: 'L4',
    source: opts.source,
    sitePageId: opts.sitePageId ?? null,
    payload: {
      types: schema.types,
      sameAs: schema.sameAs,
      blocks: schema.blocks.map((b) => ({ ok: b.ok, rawText: b.rawText })),
    },
    rawText: JSON.stringify(schema.raw),
  }
}

